import AppKit

/// The Color sub-tab's last section, **Look** (spec §11 GR-7 [b], grading
/// GR5b): the gallery of the eight built-in looks and None, the
/// imported LUTs and Import LUT… (GR-8 [b], GR6b), and an Amount row when
/// every selected clip has a look.
///
/// A tile (a LUT's too), None and Reset write the clips' OWN look in one
/// `set_video`, even with an action selected (GR-7 [b] (1)): in an action's
/// end `look: null` only stops animating the look, so it could not remove
/// one, and the kind switches at the end anyway. The Amount row is the one
/// that animates: it goes through `binding.ops(video:)` like every number.
extension VideoPane {
    // MARK: Look

    /// Every selected clip that draws has a look (evaluated, as the rows
    /// read); false for no such clip. `ClipPane`'s structure signature reads
    /// it, since it adds or removes the Amount row.
    var allLooked: Bool {
        let clips = binding.videoClips
        return !clips.isEmpty && clips.allSatisfy { binding.video($0).look != nil }
    }

    /// Some selected clip's look is a LUT and its source file is converted
    /// by Camera Log (spec §11 GR-16): a camera LUT applied as a look would
    /// then convert it twice. `ClipPane`'s structure signature reads it, since
    /// it adds or removes the warning row.
    var lutOverCameraLog: Bool {
        let snapshot = binding.snapshot
        return binding.videoClips.contains { clip in
            guard binding.video(clip).look?.kind == .lut,
                let media = clip.source.mediaID, snapshot.media(media)?.color != nil
            else { return false }
            return true
        }
    }

    /// Some selected clip's look is a LUT and the project is HDR (HLG), where
    /// a `.cube` LUT still reads its values as Rec. 709 (spec §11 HD-2, HD-13
    /// (k)). `ClipPane`'s structure signature reads it, since it adds or
    /// removes the warning row.
    var lutInHLG: Bool {
        binding.snapshot.canvas.output == .hlg
            && binding.videoClips.contains { binding.video($0).look?.kind == .lut }
    }

    func lookSection(_ gallery: LookGallery) -> InspectorSection {
        let binding = self.binding
        func ids() -> [UInt32] { binding.videoClips.map(\.id) }
        func looks() -> [LookProps?] { binding.videoClips.map { binding.video($0).look } }
        func names() -> [UInt32: String] {
            var names: [UInt32: String] = [:]
            for lut in LookGallery.luts(in: binding.snapshot) {
                names[lut.id] = LookGallery.lutName(lut)
            }
            return names
        }
        let view = LookGalleryView(
            gallery: gallery, binding: binding,
            onPick: { binding.apply("Look", [LookGallery.op($0, clips: ids())]) },
            onPickLUT: { binding.apply("Look", [LookGallery.op(lut: $0, clips: ids())]) },
            onImport: { [weak self] in
                self?.inspector?.onCommand?(#selector(EditorViewController.importLUT(_:)))
            })
        var rows: [NSView] = [view]
        if lutOverCameraLog {
            // A warning only: a creative LUT there is legitimate (GR-16).
            let warning = InspectorRowLabel(
                "This clip's file is converted by Camera Log; a camera LUT here converts it "
                    + "twice.")
            warning.lineBreakMode = .byWordWrapping
            warning.maximumNumberOfLines = 0
            rows.append(inspectorRow(nil, [warning]))
        }
        if lutInHLG {
            // A warning only, as GR-16's: a LUT keeps its 0…1 meaning.
            let warning = InspectorRowLabel(
                "This project is HDR (HLG): a .cube LUT reads its values as Rec. 709.")
            warning.lineBreakMode = .byWordWrapping
            warning.maximumNumberOfLines = 0
            rows.append(inspectorRow(nil, [warning]))
        }
        rows += allLooked ? [
            inspectorValueRow(
                "Amount", binding, name: "Amount", unit: "%", decimals: 0, min: 0, max: 100,
                quick: [0, 25, 50, 75, 100],
                read: { (binding.videoProps.look?.amount ?? 1) * 100 },
                ops: { binding.ops(video: VideoPatch(look: .some(LookPatch(amount: $0 / 100)))) },
                mixed: { binding.mixedVideo { $0.look?.amount } }),
        ] : []
        return InspectorSection(
            id: "video.look", title: "Look",
            summary: { LookGallery.summary(looks(), names: names()) },
            reset: { binding.apply("Look", [LookGallery.op(nil, clips: ids())]) },
            differs: { looks().contains { $0 != nil } },
            defaultExpanded: false,
            rows: rows)
    }
}
import AppKit

/// The Color sub-tab's **Qualifier** section (spec §11 GR-13, grading-2
/// G2-4), on adjustment clips only, after Adjustment: which of the pixels
/// behind the clip its grade reaches.
///
/// Per range two rows — its checkbox (Hue, Saturation, Luma) in the label
/// column then its strip (`RangeStripControl`), then three captioned fields
/// (Centre, Width, Soft in whole degrees; Low, High, Soft to two decimals) —
/// then Invert, then Blur (spec §11 GR-35: the house slider and field,
/// 0–100 %, one step "Qualifier Blur"), then Pick from Canvas and the Show
/// Selection switch, both sent to the editor as commands
/// (`EditorViewController+Qualifier.swift`, `+Seeing`). A checkbox writes
/// `{}` or `null` (one step named after the range); a strip drag is the live trio; a field one commit; each sends the
/// WHOLE range to every selected clip, the first clip's values being the
/// ones shown (the mixed badge says when the others differ). Every row
/// writes `video.qualifier`, so a keyed action marks them all as one key.
extension VideoPane {
    // MARK: Qualifier

    func qualifierSection() -> InspectorSection {
        let binding = self.binding
        func qualifier() -> ColorQualifier { binding.videoProps.qualifier }
        func ops(_ patch: ColorQualifierPatch) -> [ReelOp] {
            binding.ops(video: VideoPatch(qualifier: patch))
        }
        var rows: [NSView] = []
        for range in QualifierRange.allCases {
            rows += qualifierRows(range, read: qualifier, ops: ops)
        }
        rows.append(
            inspectorCheckRow(
                "Invert", binding, name: "Qualifier",
                read: { qualifier().invert },
                ops: { ops(ColorQualifierPatch(invert: $0)) },
                mixed: { binding.mixedVideo { $0.qualifier.invert } }))
        rows.append(
            inspectorValueRow(
                "Blur", binding, name: "Qualifier Blur", unit: "%", decimals: 0, min: 0,
                max: 100, quick: [0, 25, 50, 75, 100],
                read: { qualifier().blur * 100 },
                ops: { ops(ColorQualifierPatch(blur: $0 / 100)) },
                mixed: { binding.mixedVideo { $0.qualifier.blur } }))
        let pick = commandButton(
            "Pick from Canvas", #selector(EditorViewController.pickQualifier(_:)),
            toolTip: "Click the preview to centre the ranges on a colour (Esc cancels)")
        let show = OptionCheckboxControl(
            label: "Show Selection",
            read: { [weak self] in
                guard let key = self?.inspector?.document?.recipeKey else { return false }
                return RecipeSource.shared.options(for: key).selection != nil
            },
            write: { [weak self] _ in
                self?.inspector?.onCommand?(
                    #selector(EditorViewController.toggleShowSelection(_:)))
            },
            enabled: { true }, onEdit: {})
        rows.append(inspectorButtonRow([pick, show]))
        return InspectorSection(
            id: "video.qualifier", title: "Qualifier",
            summary: { qualifier().summary },
            reset: { binding.apply("Qualifier", ops(.reset)) },
            differs: { !qualifier().isNeutral },
            defaultExpanded: false,
            rows: rows)
    }

    /// One range's two rows: the checkbox and the strip, then the fields.
    private func qualifierRows(
        _ range: QualifierRange, read: @escaping () -> ColorQualifier,
        ops: @escaping (ColorQualifierPatch) -> [ReelOp]
    ) -> [NSView] {
        let binding = self.binding
        let name = range.title
        func on() -> Bool { read().isOn(range) }
        let check = OptionCheckboxControl(
            label: name, read: on,
            write: { [weak binding] value in
                binding?.apply(name, ops(.toggle(range, value)))
            },
            enabled: { true },
            onEdit: { [weak binding] in binding?.edited() })
        check.translatesAutoresizingMaskIntoConstraints = false
        check.widthAnchor.constraint(equalToConstant: InspectorMetrics.labelWidth).isActive = true
        let strip = RangeStripControl(
            kind: range, read: read,
            begin: { [weak binding] in binding?.liveBegin() },
            update: { [weak binding] patch in binding?.liveUpdate(ops(patch)) },
            end: { [weak binding] in binding?.liveEnd(name) })
        let mixed: () -> Bool
        switch range {
        case .hue: mixed = { binding.mixedVideo { $0.qualifier.hue } }
        case .saturation: mixed = { binding.mixedVideo { $0.qualifier.saturation } }
        case .luma: mixed = { binding.mixedVideo { $0.qualifier.luma } }
        }
        let stripRow = inspectorRow(
            nil, [check, strip], mixed: mixed, binding: binding, writes: ops(.reset),
            default: InspectorRowDefault(
                name: name, differs: on, ops: { ops(.toggle(range, false)) }))
        let gutter = stripRow.gutter
        strip.keyed = { [weak gutter] in gutter?.isKeyed == true }
        return [stripRow, qualifierFields(range, read: read, ops: ops)]
    }

    /// The range's three captioned fields across one row.
    private func qualifierFields(
        _ range: QualifierRange, read: @escaping () -> ColorQualifier,
        ops: @escaping (ColorQualifierPatch) -> [ReelOp]
    ) -> NSView {
        let binding = self.binding
        let name = range.title
        func on() -> Bool { read().isOn(range) }
        typealias Field = (caption: String, max: Double, get: (ColorQualifier) -> Double,
                           put: (ColorQualifier, Double) -> ColorQualifierPatch)
        let fields: [Field]
        if range == .hue {
            func hue(_ q: ColorQualifier) -> QualifierHue { q.hue ?? .initial }
            fields = [
                ("Centre", 360, { hue($0).center },
                 { q, v in var h = hue(q); h.center = v; return ColorQualifierPatch(hue: .set(h)) }),
                ("Width", 360, { hue($0).width },
                 { q, v in var h = hue(q); h.width = v; return ColorQualifierPatch(hue: .set(h)) }),
                ("Soft", 180, { hue($0).softness },
                 { q, v in var h = hue(q); h.softness = v; return ColorQualifierPatch(hue: .set(h)) }),
            ]
        } else {
            func levels(_ q: ColorQualifier) -> QualifierLevels { q.levels(range) ?? .initial }
            fields = [
                ("Low", 1, { levels($0).low },
                 { q, v in
                     var l = levels(q)
                     l.low = min(v, l.high)
                     return .levels(range, .set(l))
                 }),
                ("High", 1, { levels($0).high },
                 { q, v in
                     var l = levels(q)
                     l.high = max(v, l.low)
                     return .levels(range, .set(l))
                 }),
                ("Soft", 1, { levels($0).softness },
                 { q, v in var l = levels(q); l.softness = v; return .levels(range, .set(l)) }),
            ]
        }
        var controls: [NSView] = []
        for field in fields {
            let caption = InspectorRowLabel(field.caption)
            caption.font = DS.sans(10)
            caption.setContentCompressionResistancePriority(.required, for: .horizontal)
            controls.append(caption)
            controls.append(
                OptionFieldControl(
                    width: 41, unit: range == .hue ? "°" : "", decimals: range == .hue ? 0 : 2,
                    min: 0, max: field.max,
                    read: { field.get(read()) },
                    write: { [weak binding] value in
                        binding?.apply(name, ops(field.put(read(), value)))
                    },
                    enabled: on,
                    onEdit: { [weak binding] in binding?.edited() }))
        }
        return inspectorRow(nil, controls, binding: binding, writes: ops(.reset))
    }
}
import AppKit

/// The adjustment clip's half of the Clip tab (spec §11 GR-6): the three
/// selection tests `ClipPane` builds its sub-tabs from, and the Adjustment
/// section the Color tab opens with when every selected clip is one.
///
/// An adjustment clip draws nothing of its own — it grades everything behind
/// it in its container — so its only pixel key the chrome writes is
/// `opacity`, shown here as Strength. Picture never appears with one in the
/// selection (its transform, crop and shadow are kept in the model and not
/// drawn), and Color appears when every clip is gradable: source pixels or
/// an adjustment clip.
extension VideoPane {
    // MARK: Applicability

    /// Every selected clip is an adjustment clip; false for no selection.
    var allAdjustment: Bool {
        let clips = binding.clips
        return !clips.isEmpty && clips.allSatisfy { InspectorTab.isAdjustment($0) }
    }

    /// Some selected clip is an adjustment clip.
    var anyAdjustment: Bool {
        binding.clips.contains { InspectorTab.isAdjustment($0) }
    }

    /// Every selected clip takes a grade: it has source pixels or is an
    /// adjustment clip; false for no selection.
    var allGradable: Bool {
        let clips = binding.clips
        return !clips.isEmpty
            && clips.allSatisfy {
                InspectorTab.hasSourcePixels($0, in: binding.snapshot)
                    || InspectorTab.isAdjustment($0)
            }
    }

    // MARK: Adjustment

    /// The Color tab's first section for an all-adjustment selection:
    /// Strength, the clip's `opacity` — how much of its grade is mixed over
    /// what is behind it. The summary is the strength; Reset is full
    /// strength.
    func adjustmentSection() -> InspectorSection {
        let binding = self.binding
        return InspectorSection(
            id: "video.adjustment", title: "Adjustment",
            summary: { String(format: "%.0f%%", binding.videoProps.opacity * 100) },
            reset: { binding.apply("Adjustment", video: VideoPatch(opacity: 1)) },
            defaultExpanded: false,
            rows: [
                inspectorValueRow(
                    "Strength", binding, name: "Strength", unit: "%", decimals: 0, min: 0, max: 100,
                    quick: [0, 25, 50, 75, 100],
                    read: { binding.videoProps.opacity * 100 },
                    ops: { binding.ops(video: VideoPatch(opacity: $0 / 100)) },
                    mixed: { binding.mixedVideo { $0.opacity } }),
            ])
    }
}

import AppKit

/// The Color sub-tab's **Wheels** section (spec §11 GR-11, grading-2 G2-2):
/// Lift, Gamma and Gain across one row, each a disc for the colour push, a
/// master strip and a master field.
///
/// Every control writes only its own keys — a puck its wheel's `x, y`, a
/// strip or a field its wheel's `master` — through `binding.ops(video:)`, so a
/// write over several clips keeps each one's other values and lands on an
/// action's end when one is selected. A puck or strip drag is the live trio
/// (one undo step named after the wheel); a field, a double-click and Reset
/// commit once, and a strip's double-click off the knob first undoes its
/// first click's jump, so it too is one step (#272). The row never depends on
/// a value, so a live drag never rebuilds the pane (`structureSignature` is
/// unchanged), and it has one row mark and one mixed badge for the whole
/// `video.wheels` key (CI-7, CI-9).
extension VideoPane {
    // MARK: Wheels

    func wheelsSection() -> InspectorSection {
        let binding = self.binding
        func wheels() -> ColorWheels { binding.videoProps.wheels }
        func ops(_ patch: ColorWheelsPatch) -> [ReelOp] {
            binding.ops(video: VideoPatch(wheels: patch))
        }
        let view = ColorWheelsView(binding: binding, wheels: wheels, ops: ops)
        let row = inspectorRow(
            nil, [view], mixed: { binding.mixedVideo { $0.wheels } }, binding: binding,
            writes: ops(.neutral),
            default: .derived(binding, name: "Wheels", read: wheels) { ops(ColorWheelsView.whole($0)) })
        let gutter = row.gutter
        view.keyed = { [weak gutter] in gutter?.isKeyed == true }
        return InspectorSection(
            id: "video.wheels", title: "Wheels",
            summary: { wheels().isNeutral ? "neutral" : "adjusted" },
            reset: { binding.apply("Wheels", video: VideoPatch(wheels: .neutral)) },
            defaultExpanded: false,
            rows: [row])
    }
}

/// The Wheels row's three columns — Lift · Gamma · Gain — each a title, a
/// square-framed `ColorWheelControl`, a `WheelStripControl` and a master
/// field (2 decimals, no unit, −1…1). The disc is the column less 4 pt,
/// capped at 112 pt, so it is about 78 pt at the default pane and 70 at the
/// narrowest. Hugging 1: the row's stretchy element (`inspectorRow` gives it
/// no trailing spacer).
final class ColorWheelsView: NSView {
    static let gap: CGFloat = 4
    static let maxDisc: CGFloat = 112
    /// Whether the row is keyed; the controls ask it when they draw.
    var keyed: () -> Bool = { false }
    private(set) var discs: [ColorWheelControl] = []
    private(set) var strips: [WheelStripControl] = []
    /// `document.project` at each strip's press, while its gesture runs.
    private var stripStarts: [ColorWheelKind: ReelProject] = [:]
    /// `document.project` after each strip's release, and when, kept only
    /// when the gesture made a step (#272): the step a double-click's reset
    /// amends.
    private var stripSteps: [ColorWheelKind: (step: ReelProject, at: TimeInterval)] = [:]

    /// All nine of `wheels` as a patch: the row default's write.
    static func whole(_ wheels: ColorWheels) -> ColorWheelsPatch {
        func patch(_ wheel: ColorWheel) -> ColorWheelPatch {
            ColorWheelPatch(x: wheel.x, y: wheel.y, master: wheel.master)
        }
        return ColorWheelsPatch(
            lift: patch(wheels.lift), gamma: patch(wheels.gamma), gain: patch(wheels.gain))
    }

    init(
        binding: InspectorBinding, wheels: @escaping () -> ColorWheels,
        ops: @escaping (ColorWheelsPatch) -> [ReelOp]
    ) {
        super.init(frame: .zero)
        translatesAutoresizingMaskIntoConstraints = false
        setContentHuggingPriority(NSLayoutConstraint.Priority(1), for: .horizontal)
        setContentCompressionResistancePriority(NSLayoutConstraint.Priority(1), for: .horizontal)
        var previous: NSView?
        for kind in ColorWheelKind.allCases {
            let column = makeColumn(kind, binding: binding, wheels: wheels, ops: ops)
            addSubview(column)
            NSLayoutConstraint.activate([
                column.topAnchor.constraint(equalTo: topAnchor),
                column.bottomAnchor.constraint(equalTo: bottomAnchor),
            ])
            if let previous {
                column.leadingAnchor.constraint(equalTo: previous.trailingAnchor, constant: Self.gap)
                    .isActive = true
                column.widthAnchor.constraint(equalTo: previous.widthAnchor).isActive = true
            } else {
                column.leadingAnchor.constraint(equalTo: leadingAnchor).isActive = true
            }
            previous = column
        }
        previous?.trailingAnchor.constraint(equalTo: trailingAnchor).isActive = true
    }

    @available(*, unavailable)
    required init?(coder: NSCoder) {
        fatalError("ColorWheelsView does not support NSCoder")
    }

    private func makeColumn(
        _ kind: ColorWheelKind, binding: InspectorBinding,
        wheels: @escaping () -> ColorWheels, ops: @escaping (ColorWheelsPatch) -> [ReelOp]
    ) -> NSView {
        func wheel() -> ColorWheel { kind.wheel(wheels()) }
        func push() -> (x: Double, y: Double) { (wheel().x, wheel().y) }
        func master() -> Double { wheel().master }
        let name = kind.title
        let title = InspectorRowLabel(name)
        title.alignment = .center
        // A label hugs at 250, above the stack's pull, and would hold the
        // column to its own width; the column is the row's to size.
        title.setContentHuggingPriority(NSLayoutConstraint.Priority(1), for: .horizontal)
        let disc = ColorWheelControl(
            read: push,
            write: { [weak binding] x, y in
                // A puck sends its wheel's push alone, never the master.
                let moved = ColorWheelPatch(x: x, y: y)
                binding?.liveUpdate(ops(kind.patch(moved)))
            },
            begin: { [weak binding] in binding?.liveBegin() },
            end: { [weak binding] in binding?.liveEnd(name) },
            reset: { [weak binding] in
                binding?.apply(name, ops(kind.patch(ColorWheelPatch(x: 0, y: 0))))
            },
            enabled: { true },
            start: { [weak binding] in
                guard let binding, let x = binding.startValue({ push().x }),
                      let y = binding.startValue({ push().y })
                else { return nil }
                return (x, y)
            },
            now: { [weak binding] in
                guard let binding, let x = binding.nowValue({ push().x }),
                      let y = binding.nowValue({ push().y })
                else { return nil }
                return (x, y)
            })
        let strip = WheelStripControl(
            read: master,
            write: { [weak binding] value in
                binding?.liveUpdate(ops(kind.patch(ColorWheelPatch(master: value))))
            },
            begin: { [weak self, weak binding] in self?.stripBegan(kind, binding: binding) },
            end: { [weak self, weak binding] in
                self?.stripEnded(kind, name: name, binding: binding)
            },
            reset: { [weak self, weak binding] in
                self?.stripReset(
                    kind, name: name, binding: binding,
                    ops: ops(kind.patch(ColorWheelPatch(master: 0))))
            },
            enabled: { true },
            start: { [weak binding] in binding?.startValue(master) },
            now: { [weak binding] in binding?.nowValue(master) })
        let field = OptionFieldControl(
            width: InspectorMetrics.fieldWidth, unit: "", decimals: 2, min: -1, max: 1,
            read: master,
            write: { [weak binding] value in
                binding?.apply(name, ops(kind.patch(ColorWheelPatch(master: value))))
            },
            enabled: { true },
            onEdit: { [weak binding] in binding?.edited() })
        disc.keyed = { [weak self] in self?.keyed() ?? false }
        strip.keyed = { [weak self] in self?.keyed() ?? false }
        discs.append(disc)
        strips.append(strip)

        let column = NSView()
        column.translatesAutoresizingMaskIntoConstraints = false
        for view in [title, disc, strip, field] as [NSView] {
            view.translatesAutoresizingMaskIntoConstraints = false
            column.addSubview(view)
        }
        // The disc is the column less 4 pt, square, never past `maxDisc`; the
        // fill is a lower priority than the cap so a wide pane stops at 112.
        let fill = disc.widthAnchor.constraint(equalTo: column.widthAnchor, constant: -Self.gap)
        fill.priority = NSLayoutConstraint.Priority(750)
        NSLayoutConstraint.activate([
            title.topAnchor.constraint(equalTo: column.topAnchor),
            title.leadingAnchor.constraint(equalTo: column.leadingAnchor),
            title.trailingAnchor.constraint(equalTo: column.trailingAnchor),
            disc.topAnchor.constraint(equalTo: title.bottomAnchor, constant: 4),
            disc.centerXAnchor.constraint(equalTo: column.centerXAnchor),
            disc.heightAnchor.constraint(equalTo: disc.widthAnchor),
            disc.widthAnchor.constraint(lessThanOrEqualToConstant: Self.maxDisc),
            disc.widthAnchor.constraint(lessThanOrEqualTo: column.widthAnchor),
            fill,
            strip.topAnchor.constraint(equalTo: disc.bottomAnchor, constant: 6),
            strip.leadingAnchor.constraint(equalTo: disc.leadingAnchor),
            strip.trailingAnchor.constraint(equalTo: disc.trailingAnchor),
            strip.heightAnchor.constraint(equalToConstant: 13),
            field.topAnchor.constraint(equalTo: strip.bottomAnchor, constant: 4),
            field.centerXAnchor.constraint(equalTo: column.centerXAnchor),
            field.bottomAnchor.constraint(equalTo: column.bottomAnchor),
        ])
        return column
    }

    // MARK: The strip's double-click (#272)

    /// A strip's press: the handle it starts from, then the live trio.
    private func stripBegan(_ kind: ColorWheelKind, binding: InspectorBinding?) {
        stripStarts[kind] = binding?.document?.project
        stripSteps[kind] = nil
        binding?.liveBegin()
    }

    /// A strip's release: the live trio's end, then the handle it left,
    /// kept only when the gesture registered a step (the handle moved).
    private func stripEnded(_ kind: ColorWheelKind, name: String, binding: InspectorBinding?) {
        binding?.liveEnd(name)
        if let after = binding?.document?.project, after !== stripStarts[kind] {
            stripSteps[kind] = (after, ProcessInfo.processInfo.systemUptime)
        }
        stripStarts[kind] = nil
    }

    /// A strip's double-click: the reset amends the step its first click
    /// left when that release is within the double-click interval — so an
    /// earlier gesture's step is never reused — and is its own step
    /// otherwise.
    private func stripReset(
        _ kind: ColorWheelKind, name: String, binding: InspectorBinding?, ops: [ReelOp]
    ) {
        let last = stripSteps.removeValue(forKey: kind)
        if let last,
            ProcessInfo.processInfo.systemUptime - last.at <= NSEvent.doubleClickInterval
        {
            binding?.amend(name, ops, step: last.step)
        } else {
            binding?.apply(name, ops)
        }
    }
}
import AppKit

/// The Color sub-tab's **Curves** section (spec §11 GR-12, grading-2 G2-3):
/// the channel picker, the curve plot and the selected point's In and Out
/// fields with its Delete button, in one row (`CurvesView`). The picker's
/// Hue and Sat cells edit the hue curves (spec §11 GR-32) in the same plot,
/// in their own units.
///
/// Every write sends the edited channel's WHOLE list (a list replaces, GR-12)
/// to every selected clip through `binding.ops(video:)`, so it lands on an
/// action's end when one is selected, a count change included (spec §11
/// GR-34: two curves of different counts blend). A drag is the live trio and
/// every other edit one commit, each one undo step named "Curves". The row
/// never depends on a value, so a live drag never rebuilds the pane, and it
/// has one row mark and one mixed badge for the whole `video.curves` key
/// (CI-7, CI-9).
extension VideoPane {
    // MARK: Curves

    func curvesSection(_ state: CurveEditorState) -> InspectorSection {
        let binding = self.binding
        func curves() -> ColorCurves { binding.videoProps.curves }
        func ops(_ patch: ColorCurvesPatch) -> [ReelOp] {
            binding.ops(video: VideoPatch(curves: patch))
        }
        let view = CurvesView(binding: binding, state: state, curves: curves, ops: ops)
        let row = inspectorRow(
            nil, [view], mixed: { binding.mixedVideo { $0.curves } }, binding: binding,
            writes: ops(.reset),
            default: InspectorRowDefault(
                name: "Curves", differs: { !curves().isIdentity },
                ops: { [weak binding] in binding?.curvesReset(CurveChannel.allCases) ?? [] }))
        let gutter = row.gutter
        view.editor.keyed = { [weak gutter] in gutter?.isKeyed == true }
        return InspectorSection(
            id: "video.curves", title: "Curves",
            summary: { curves().isIdentity ? "neutral" : "adjusted" },
            reset: { [weak view] in view?.reset(CurveChannel.allCases) },
            defaultExpanded: false,
            rows: [row])
    }
}

extension InspectorBinding {
    /// Reset's ops for `channels` (GR-12, GR-32): a clip outside an action
    /// has them removed from its base (`null`); a clip inside one has each
    /// channel whose edited curve is not its domain's identity written to the
    /// end AS that identity, which an end keeps as "animate to neutral" — a
    /// `null` there would only stop animating it. None when nothing would
    /// change.
    func curvesReset(_ channels: [CurveChannel]) -> [ReelOp] {
        var ops: [ReelOp] = []
        var bases: [UInt32] = []
        for clip in videoClips {
            guard action(clip) != nil else {
                bases.append(clip.id)
                continue
            }
            let named = channels.filter { !$0.domain.isIdentity(editedCurve(clip, $0)) }
            if !named.isEmpty {
                ops += self.ops(video: VideoPatch(curves: .neutral(named)), for: clip)
            }
        }
        if !bases.isEmpty {
            var removed = ColorCurvesPatch()
            for channel in channels { removed = removed.setting(channel, .some(nil)) }
            ops.insert(.setVideo(clips: bases, patch: VideoPatch(curves: removed)), at: 0)
        }
        return ops
    }
}

/// What the Curves section remembers between rebuilds, per window (owned by
/// `ClipPane`, never saved): the channel being edited (Master when a window
/// opens), the selected point's index, and `working` — an edited list not
/// yet written, held while the channel reads back as the identity of a
/// different count (a point just added to a straight channel, which writes
/// nothing until it first moves).
final class CurveEditorState {
    var channel: CurveChannel = .master
    var selected: Int?
    var working: [CurvePoint]?

    /// A channel change, Esc, a selection change: no point, no working list.
    func clear() {
        selected = nil
        working = nil
    }
}

/// The Curves row: the channel picker over the plot, square, the row's width
/// less nothing (the row's gutter is already off it) and never past
/// `maxPlot` — about 254 pt at the default pane, 230 at the narrowest — then
/// the selected point's In and Out (on a tone curve 3 decimals, 0–1; on a
/// hue curve In in degrees and Out in degrees or ×; blank and disabled with
/// no point) and Delete. Hugging 1: the row's stretchy element
/// (`inspectorRow` gives it no trailing spacer).
final class CurvesView: NSView {
    static let maxPlot: CGFloat = 300
    let editor: CurveEditorView
    let picker: CurveChannelPicker
    private let state: CurveEditorState
    private weak var binding: InspectorBinding?

    init(
        binding: InspectorBinding, state: CurveEditorState,
        curves: @escaping () -> ColorCurves, ops: @escaping (ColorCurvesPatch) -> [ReelOp]
    ) {
        self.state = state
        self.binding = binding
        editor = CurveEditorView(
            state: state, read: { curves().points($0) },
            start: { [weak binding] channel in
                guard let binding, binding.selectedAction != nil else { return nil }
                return binding.at(.start) { curves().points(channel) }
            },
            write: { [weak binding] list in
                binding?.liveUpdate(ops(.channel(state.channel, list)))
            },
            begin: { [weak binding] in binding?.liveBegin() },
            end: { [weak binding] in binding?.liveEnd("Curves") },
            commit: { [weak binding] list in
                binding?.apply("Curves", ops(.channel(state.channel, list)))
            })
        picker = CurveChannelPicker(state: state, curves: curves)
        super.init(frame: .zero)
        translatesAutoresizingMaskIntoConstraints = false
        setContentHuggingPriority(NSLayoutConstraint.Priority(1), for: .horizontal)
        setContentCompressionResistancePriority(NSLayoutConstraint.Priority(1), for: .horizontal)
        picker.onSelect = { [weak self] channel in self?.choose(channel) }
        picker.onReset = { [weak self] channel in self?.reset([channel]) }

        let editor = self.editor
        let inField = CurvePointField(
            axis: .x, domain: { state.channel.domain },
            read: { [weak editor] in editor?.selectedPoint?.x },
            write: { [weak editor] value in editor?.place(x: value) },
            onEdit: { [weak binding] in binding?.edited() })
        let outField = CurvePointField(
            axis: .y, domain: { state.channel.domain },
            read: { [weak editor] in editor?.selectedPoint?.y },
            write: { [weak editor] value in editor?.place(y: value) },
            onEdit: { [weak binding] in binding?.edited() })
        let delete = OptionButtonControl(
            title: "Delete", action: { [weak editor] in editor?.deleteSelected() },
            enabled: { [weak editor] in editor?.canDelete == true },
            onEdit: { [weak binding] in binding?.edited() })
        let fields = NSStackView(views: [
            InspectorRowLabel("In"), inField, InspectorRowLabel("Out"), outField, NSView(), delete,
        ])
        fields.orientation = .horizontal
        fields.spacing = 6
        editor.onSelection = { [weak fields, weak picker] in
            if let fields { refreshOptionControls(in: fields) }
            picker?.needsDisplay = true
        }

        for view in [picker, editor, fields] as [NSView] {
            view.translatesAutoresizingMaskIntoConstraints = false
            addSubview(view)
        }
        // The plot is the row's width, square, never past `maxPlot`; the fill
        // is a lower priority than the cap so a wide pane stops at 300.
        let fill = editor.widthAnchor.constraint(equalTo: widthAnchor)
        fill.priority = NSLayoutConstraint.Priority(750)
        NSLayoutConstraint.activate([
            // The picker and the point row line up with the plot's frame,
            // drawn `inset` − 0.5 inside the editor's bounds.
            picker.topAnchor.constraint(equalTo: topAnchor),
            picker.leadingAnchor.constraint(equalTo: editor.leadingAnchor, constant: 3),
            picker.trailingAnchor.constraint(equalTo: editor.trailingAnchor, constant: -3),
            picker.heightAnchor.constraint(equalToConstant: CurveChannelPicker.height),
            editor.topAnchor.constraint(equalTo: picker.bottomAnchor, constant: 6),
            editor.leadingAnchor.constraint(equalTo: leadingAnchor),
            editor.heightAnchor.constraint(equalTo: editor.widthAnchor),
            editor.widthAnchor.constraint(lessThanOrEqualToConstant: Self.maxPlot),
            editor.widthAnchor.constraint(lessThanOrEqualTo: widthAnchor),
            fill,
            fields.topAnchor.constraint(equalTo: editor.bottomAnchor, constant: 6),
            fields.leadingAnchor.constraint(equalTo: editor.leadingAnchor, constant: 3),
            fields.trailingAnchor.constraint(equalTo: editor.trailingAnchor, constant: -3),
            fields.bottomAnchor.constraint(equalTo: bottomAnchor),
        ])
    }

    @available(*, unavailable)
    required init?(coder: NSCoder) {
        fatalError("CurvesView does not support NSCoder")
    }

    /// A picker cell: the channel is edited from now on, with no point.
    func choose(_ channel: CurveChannel) {
        guard channel != state.channel else { return }
        editor.deselect()
        state.channel = channel
        binding?.edited()
    }

    /// The section's Reset (all six) or a cell's "Reset <Channel>": one
    /// commit "Curves" of `InspectorBinding.curvesReset`, nothing when it
    /// would change nothing.
    func reset(_ channels: [CurveChannel]) {
        editor.deselect()
        guard let binding else { return }
        let ops = binding.curvesReset(channels)
        guard !ops.isEmpty else { return }
        binding.apply("Curves", ops)
    }
}

/// A point's axis: In is x, Out is y.
enum CurveAxis { case x, y }

/// One of the point's two fields: an `OptionFieldControl` per domain (spec
/// §11 GR-32), each fixed at its build with that domain's unit, decimals and
/// range for its axis — tone 3 decimals 0–1; In on a hue curve "°" 1 decimal
/// 0–359.9; Out "°" 1 decimal −180…180 on Hue, "×" 2 decimals 0–2 on Sat —
/// the one matching `domain()` shown while a point is selected, and a blank,
/// disabled box of the same size while none is.
final class CurvePointField: NSView, OptionControl {
    private let fields: [(domain: CurveDomain, control: OptionFieldControl)]
    private let blank = NSView()
    private let read: () -> Double?
    private let domain: () -> CurveDomain

    init(axis: CurveAxis, domain: @escaping () -> CurveDomain,
         read: @escaping () -> Double?, write: @escaping (Double) -> Void,
         onEdit: @escaping () -> Void) {
        self.read = read
        self.domain = domain
        fields = [CurveDomain.tone, .hueShift, .hueGain].map { d in
            let (unit, decimals) = Self.format(d, axis)
            let low = axis == .x ? d.lower.x : d.lower.y
            let high = axis == .x ? d.upper.x : d.upper.y
            let control = OptionFieldControl(
                width: InspectorMetrics.fieldWidth, unit: unit, decimals: decimals, min: low,
                max: high, read: { read() ?? 0 }, write: write,
                enabled: { read() != nil && domain() == d }, onEdit: onEdit)
            return (d, control)
        }
        super.init(frame: .zero)
        blank.wantsLayer = true
        blank.layer?.borderWidth = 1
        blank.alphaValue = 0.42
        for view in fields.map(\.control) + [blank] {
            view.translatesAutoresizingMaskIntoConstraints = false
            addSubview(view)
            NSLayoutConstraint.activate([
                view.leadingAnchor.constraint(equalTo: leadingAnchor),
                view.trailingAnchor.constraint(equalTo: trailingAnchor),
                view.topAnchor.constraint(equalTo: topAnchor),
                view.bottomAnchor.constraint(equalTo: bottomAnchor),
            ])
        }
        refresh()
    }

    @available(*, unavailable)
    required init?(coder: NSCoder) {
        fatalError("CurvePointField does not support NSCoder")
    }

    /// A domain's unit and decimals on `axis`.
    private static func format(_ domain: CurveDomain, _ axis: CurveAxis) -> (String, Int) {
        switch (domain, axis) {
        case (.tone, _): return ("", 3)
        case (_, .x), (.hueShift, .y): return ("°", 1)
        case (.hueGain, .y): return ("×", 2)
        }
    }

    override var intrinsicContentSize: NSSize { fields[0].control.intrinsicContentSize }

    func refresh() {
        let active = read() != nil
        let shown = domain()
        for (d, control) in fields {
            control.isHidden = !(active && d == shown)
            control.refresh()
        }
        blank.isHidden = active
        effectiveAppearance.performAsCurrentDrawingAppearance {
            blank.layer?.borderColor = DS.border.cgColor
            blank.layer?.backgroundColor = NSColor.controlBackgroundColor.cgColor
        }
    }

    override func viewDidChangeEffectiveAppearance() {
        super.viewDidChangeEffectiveAppearance()
        refresh()
    }
}

/// The channel picker (owner choice 5): six equal text cells, Master · Red
/// · Green · Blue · Hue · Sat (spec §11 GR-32), the chosen one framed and
/// labelled in its channel's tint, a 3 pt dot under each channel that is not
/// its domain's identity, and "Reset <Channel>" in each cell's context menu
/// (choice 7). The labels are 10 pt (`labelSize`).
final class CurveChannelPicker: NSView, OptionControl {
    static let height: CGFloat = 24
    /// The cells' label size (GR-32 owner choice 3: 11 pt while every label
    /// fits its cell less 2 pt at the 230 pt plot, else 10). Six cells at 11
    /// pt leave "Master" 37.9 pt of a 38 pt cell (`curves_probe.swift` P19,
    /// T4-2), so 10.
    static let labelSize: CGFloat = 10
    private let state: CurveEditorState
    private let curves: () -> ColorCurves
    var onSelect: (CurveChannel) -> Void = { _ in }
    var onReset: (CurveChannel) -> Void = { _ in }

    init(state: CurveEditorState, curves: @escaping () -> ColorCurves) {
        self.state = state
        self.curves = curves
        super.init(frame: .zero)
        wantsLayer = true
    }

    @available(*, unavailable)
    required init?(coder: NSCoder) {
        fatalError("CurveChannelPicker does not support NSCoder")
    }

    func refresh() { needsDisplay = true }

    /// Equal cells sharing their 1 pt borders.
    func cellRect(_ index: Int) -> NSRect {
        let count = CGFloat(CurveChannel.allCases.count)
        let step = (bounds.width - 1) / count
        let left = (CGFloat(index) * step).rounded()
        let right = (CGFloat(index + 1) * step).rounded() + 1
        return NSRect(x: left, y: 0, width: right - left, height: bounds.height)
    }

    private func channel(at event: NSEvent) -> CurveChannel? {
        let point = convert(event.locationInWindow, from: nil)
        return CurveChannel.allCases.indices.first { cellRect($0).contains(point) }
            .map { CurveChannel.allCases[$0] }
    }

    override func mouseDown(with event: NSEvent) {
        if let channel = channel(at: event) { onSelect(channel) }
    }

    override func menu(for event: NSEvent) -> NSMenu? {
        guard let channel = channel(at: event) else { return nil }
        let menu = NSMenu()
        let item = NSMenuItem(
            title: "Reset \(channel.title)", action: #selector(resetPicked(_:)), keyEquivalent: "")
        item.target = self
        item.representedObject = channel.rawValue
        item.isEnabled = !channel.domain.isIdentity(curves().points(channel))
        menu.autoenablesItems = false
        menu.addItem(item)
        return menu
    }

    @objc private func resetPicked(_ sender: NSMenuItem) {
        guard let raw = sender.representedObject as? String,
              let channel = CurveChannel(rawValue: raw)
        else { return }
        onReset(channel)
    }

    override func draw(_ dirtyRect: NSRect) {
        let all = CurveChannel.allCases
        let order = all.indices.filter { all[$0] != state.channel }
            + all.indices.filter { all[$0] == state.channel }
        let current = curves()
        for index in order {
            let channel = all[index]
            let rect = cellRect(index)
            let chosen = channel == state.channel
            NSColor.controlBackgroundColor.setFill()
            rect.fill()
            (chosen ? channel.tint : DS.border).setStroke()
            NSBezierPath(rect: rect.insetBy(dx: 0.5, dy: 0.5)).stroke()
            let label = NSAttributedString(
                string: channel.title,
                attributes: [
                    .font: DS.sans(Self.labelSize, weight: .semibold),
                    .foregroundColor: chosen ? channel.tint : DS.textMuted,
                ])
            let size = label.size()
            label.draw(at: NSPoint(x: (rect.midX - size.width / 2).rounded(),
                                   y: rect.midY - size.height / 2 + 2))
            if !channel.domain.isIdentity(current.points(channel)) {
                channel.tint.setFill()
                NSRect(x: (rect.midX - 1.5).rounded(), y: rect.minY + 3, width: 3, height: 3).fill()
            }
        }
    }
}

import AppKit

/// The Look section's gallery model (spec §11 GR-7 [b], grading GR5b):
/// which clips a look applies to, the op a tile or a menu item sends,
/// and the nine thumbnails — None and the eight — each the composited frame
/// with that tile's click applied, then one per imported `.cube` LUT (spec
/// §11 GR-8 [b]), in the media list's order.
///
/// **It lives on `ClipPane`, not on the view**, because the pane rebuilds its
/// sections on every structure change and a thumbnail set that died with each
/// build would re-render for nothing. A view attaches itself (`view`) when it
/// is built, and an update from any other view — a retired build's late
/// `viewDidMoveToWindow` — is ignored.
///
/// **When it renders.** Its inputs are the edited project's HANDLE, the target
/// ids and the thumbnail time. An update or a playhead poke with the inputs it
/// last scheduled does nothing; anything else re-arms one `settle` timer, so a
/// playhead moving every frame (playback, a scrub) never renders. The timer
/// renders only if the gallery is open then (its section expanded, its window
/// there); hiding it or leaving the window cancels the timer and supersedes a
/// running generation. A generation applies the trial ops (the nine, then one
/// per LUT) on main and renders them off main, one tile after another, through
/// `Exporter.renderFrame` — `render_frame`'s renderer, so a thumbnail is the
/// pixels that tool writes (its file carries PR-11's label; a tile's dump is
/// unlabelled, spec §11 PR-11) —
/// with `RecipeOptions.none` (thumbnails ignore Show Ungraded, as an export
/// does). A superseded generation skips its remaining tiles, and its results
/// never land.
final class LookGallery {
    /// None, then the eight in the core's order: the gallery's reading order.
    static let tiles: [LookKind?] = [nil] + LookKind.builtIns.map { Optional($0) }
    static let thumbnailWidth = 256
    static let settle: TimeInterval = 0.3
    #if FRAMEJOB_DEV_TOOLS
    /// A launch default naming a folder: each completed generation N writes
    /// `<folder>/<N>/<tile>.png` and then `<folder>/<N>/manifest.json`.
    static let dumpKey = "RCDevLookGalleryDump"
    #endif

    private(set) var thumbnails: [CGImage?] = Array(repeating: nil, count: tiles.count)
    /// The Imported group's thumbnails, by the LUT's media id.
    private(set) var lutThumbnails: [UInt32: CGImage] = [:]
    /// The attached view; an update from any other is ignored.
    weak var view: LookGalleryView?

    private struct Inputs {
        let project: ReelProject
        let ids: [UInt32]
        let time: Ticks

        func same(_ other: Inputs?) -> Bool {
            guard let other else { return false }
            return project === other.project && ids == other.ids && time == other.time
        }
    }

    /// A generation's cancel flag, read off main between tiles.
    private final class Token {
        private let lock = NSLock()
        private var cancelled = false
        func cancel() {
            lock.lock()
            cancelled = true
            lock.unlock()
        }
        var isCancelled: Bool {
            lock.lock()
            defer { lock.unlock() }
            return cancelled
        }
    }

    private weak var document: ProjectDocument?
    private var targets: [ClipSnapshot] = []
    private var open = false
    /// What the last update or poke asked for, what was last scheduled (timer
    /// armed, rendering or rendered), and what the thumbnails show.
    private var latest: Inputs?
    private var scheduled: Inputs?
    private var rendered: Inputs?
    private var timer: Timer?
    private var running: Token?
    private var generation = 0

    /// The one serial queue the generations render on (a one-frame render
    /// queue, beside the eyedropper's and Save Frame's).
    private static let queue = DispatchQueue(label: "com.kgalligan.framejob.lookGallery")
    /// Every gallery, weakly, for `playheadMoved(in:)`. Main thread.
    private static let live = NSHashTable<LookGallery>.weakObjects()

    init() {
        Self.live.add(self)
    }

    /// Open, and either asked for inputs it has not shown or still rendering.
    var isPending: Bool {
        guard open, let latest else { return false }
        return !latest.same(rendered) || running != nil
    }

    // MARK: - Updates

    func update(
        from view: LookGalleryView, document: ProjectDocument?, targets: [ClipSnapshot],
        open: Bool
    ) {
        guard view === self.view else { return }
        self.document = document
        self.targets = targets
        self.open = open
        reschedule()
    }

    /// The playhead moved in `document`: each of its live galleries asks again.
    static func playheadMoved(in document: ProjectDocument) {
        for gallery in live.allObjects where gallery.document === document {
            gallery.reschedule()
        }
    }

    private func reschedule() {
        guard open, let document, let first = targets.first else {
            latest = nil
            cancel()
            return
        }
        let inputs = Inputs(
            project: document.editedProject, ids: targets.map(\.id),
            time: Self.time(first: first, playhead: document.playhead))
        latest = inputs
        if inputs.same(scheduled) { return }
        cancel()
        scheduled = inputs
        if inputs.same(rendered) { return }
        let timer = Timer(timeInterval: Self.settle, repeats: false) { [weak self] _ in
            self?.fire()
        }
        RunLoop.main.add(timer, forMode: .common)
        self.timer = timer
    }

    /// Stops the timer and supersedes a running generation; what was last
    /// scheduled falls back to what the thumbnails show.
    private func cancel() {
        timer?.invalidate()
        timer = nil
        running?.cancel()
        running = nil
        scheduled = rendered
    }

    // MARK: - A generation

    private func fire() {
        timer = nil
        guard open, let view, view.window != nil, let document, let inputs = scheduled,
              !inputs.same(rendered)
        else {
            // Nothing rendered, so a later update with these inputs must arm again.
            scheduled = rendered
            return
        }
        generation += 1
        let number = generation
        let token = Token()
        running = token
        func trial(_ edit: ReelEdit?) -> ReelProject? {
            switch edit {
            case .applied(let project)?: return project
            case .identity?: return inputs.project
            default: return nil
            }
        }
        let luts = Self.luts(in: inputs.project.snapshot).map(\.id)
        let trials: [ReelProject?] = Self.tiles.map { tile in
            trial(try? inputs.project.applying(Self.op(tile, clips: inputs.ids)))
        } + luts.map { lut in
            trial(try? inputs.project.applying(Self.op(lut: lut, clips: inputs.ids)))
        }
        let urls = document.mediaURLs()
        let graphics = GraphicRegistry.shared.snapshot(for: document.recipeKey)
        var dump: URL?
        #if FRAMEJOB_DEV_TOOLS
        if let folder = UserDefaults.standard.string(forKey: Self.dumpKey), !folder.isEmpty {
            dump = URL(fileURLWithPath: folder).appendingPathComponent(String(number))
        }
        #endif
        Self.queue.async { [weak self] in
            var images: [CGImage?] = []
            for trial in trials {
                if token.isCancelled { return }
                images.append(trial.flatMap {
                    Exporter.renderFrame(
                        project: $0, urls: urls, at: inputs.time, maxWidth: Self.thumbnailWidth,
                        options: .none, graphics: graphics)
                })
            }
            if token.isCancelled { return }
            let names = Self.tiles.map { $0?.rawValue ?? "none" } + luts.map { "lut-\($0)" }
            if let dump { Self.write(images, names, generation: number, inputs: inputs, to: dump) }
            DispatchQueue.main.async {
                guard let self, self.running === token, !token.isCancelled else { return }
                self.running = nil
                self.thumbnails = Array(images.prefix(Self.tiles.count))
                self.lutThumbnails = [:]
                for (lut, image) in zip(luts, images.dropFirst(Self.tiles.count)) {
                    self.lutThumbnails[lut] = image
                }
                self.rendered = inputs
                self.view?.showThumbnails()
            }
        }
    }

    /// The dev dump: the PNGs (the nine, then `lut-<id>`), then the
    /// manifest, last, with `tiles` the names in order.
    private static func write(
        _ images: [CGImage?], _ names: [String], generation: Int, inputs: Inputs, to folder: URL
    ) {
        try? FileManager.default.createDirectory(at: folder, withIntermediateDirectories: true)
        var missing: [String] = []
        for (name, image) in zip(names, images) {
            guard let image else {
                missing.append(name)
                continue
            }
            _ = try? FrameWriter.write(
                image, as: .png, to: folder.appendingPathComponent(name + ".png"))
        }
        let manifest: [String: Any] = [
            "generation": generation, "t": inputs.time, "clips": inputs.ids, "missing": missing,
            "tiles": names,
        ]
        if let data = try? JSONSerialization.data(withJSONObject: manifest) {
            try? data.write(to: folder.appendingPathComponent("manifest.json"))
        }
    }

    // MARK: - Pure answers

    /// The clips a look applies to: those that draw and take a grade —
    /// source pixels of their own, or an adjustment clip.
    static func targets(_ clips: [ClipSnapshot], in snapshot: ProjectSnapshot) -> [ClipSnapshot] {
        clips.filter {
            InspectorTab.hasPixels($0, in: snapshot)
                && (InspectorTab.hasSourcePixels($0, in: snapshot) || InspectorTab.isAdjustment($0))
        }
    }

    /// What a tile or a menu item sends: the kind alone, so each clip keeps
    /// its amount (1 on a clip with none), or `look: null` for None.
    static func op(_ kind: LookKind?, clips: [UInt32]) -> ReelOp {
        .setVideo(clips: clips, patch: VideoPatch(look: .some(kind.map { LookPatch(kind: $0) })))
    }

    /// What a LUT's tile or menu item sends: `{kind: lut, media}`, no amount.
    static func op(lut media: UInt32, clips: [UInt32]) -> ReelOp {
        .setVideo(clips: clips, patch: VideoPatch(look: .some(LookPatch(kind: .lut, media: media))))
    }

    /// The project's `.cube` LUTs, in the media list's order (GR-8 [b]).
    static func luts(in snapshot: ProjectSnapshot) -> [MediaSnapshot] {
        snapshot.media.filter { $0.kind == .lut }
    }

    /// A LUT's tile and item title: its name less a trailing `.cube`.
    static func lutName(_ media: MediaSnapshot) -> String {
        let name = media.name
        return name.lowercased().hasSuffix(".cube") ? String(name.dropLast(5)) : name
    }

    /// The thumbnail time: the playhead inside the first clip, else its first
    /// frame.
    static func time(first: ClipSnapshot, playhead: Ticks) -> Ticks {
        first.start <= playhead && playhead < first.end ? playhead : first.start
    }

    /// `.some(kind)` when every look is that kind, `.some(nil)` when none has
    /// a look, nil when they disagree or there are none.
    static func shared(_ looks: [LookProps?]) -> LookKind?? {
        guard let first = looks.first else { return nil }
        let kind = first?.kind
        return looks.allSatisfy({ $0?.kind == kind }) ? .some(kind) : nil
    }

    /// "Warm 80%" when kind, LUT and amount are shared (a LUT by `names`,
    /// "LUT" when it has none), "none" when no clip has a look, "mixed"
    /// otherwise.
    static func summary(_ looks: [LookProps?], names: [UInt32: String] = [:]) -> String {
        guard let first = looks.first else { return "none" }
        guard looks.allSatisfy({ $0 == first }) else { return "mixed" }
        guard let look = first else { return "none" }
        let name = look.kind == .lut ? look.media.flatMap { names[$0] } ?? "LUT"
            : look.kind.displayName
        return name + String(format: " %.0f%%", look.amount * 100)
    }
}
